import { _decorator, Component, director, Node, sp, tween, Tween, UIOpacity, Vec3 } from 'cc';
import { trySetAnimation } from '../utils/SpineSafe';
import StoreManager from '../store/StoreManager';
import { GameViewAdapter } from './GameViewAdapter';
import { GAME_EVENT_TYPE, gameRuntimeEventBus } from '../events/GameRuntimeEventBus';

const { ccclass, property } = _decorator;

// 自動關閉秒數
const AUTO_DISMISS_SEC = 10;
// end 播完後整個彈窗淡出到透明的秒數
const CLOSE_FADE_SEC = 1.5;
// end 沒播完回呼時的保底秒數
const END_FALLBACK_SEC = 1.5;
// 縮放覆寫的內容節點
const CONTENT_NODE_NAME = 'popup';

@ccclass('1002/FreeBoardView')
export class FreeBoardView extends Component {

    @property(sp.Skeleton)
    spine: sp.Skeleton = null!;

    private _resolveClose: (() => void) | null = null;
    private _dismissed = false;
    private _fading = false;
    private readonly autoDismiss = (): void => this.dismiss();
    private readonly finishClose = (): void => this.close();

    private disposeOrientation: (() => void) | null = null;
    private contentDefaults: { position: Vec3; scale: Vec3 } | null = null;

    protected override onLoad(): void {
        this.node.on(Node.EventType.TOUCH_START, this.onTouchStart, this);
        this.applyAdapterOverride();
        this.disposeOrientation = gameRuntimeEventBus.on(GAME_EVENT_TYPE.DEVICE_ORIENTATION_CHANGED, () => {
            this.applyAdapterOverride();
        });
    }

    private applyAdapterOverride(): void {
        const content = this.node.getChildByName(CONTENT_NODE_NAME);
        if (!content) {
            console.warn(`[FreeBoard] content node '${CONTENT_NODE_NAME}' not found`);
            return;
        }
        if (!this.contentDefaults) {
            this.contentDefaults = { position: content.position.clone(), scale: content.scale.clone() };
        }
        content.setPosition(this.contentDefaults.position);
        content.setScale(this.contentDefaults.scale);
        const isPortrait = StoreManager.getInstance().getDeviceStore().isPortrait;
        const adapterName = isPortrait ? 'GameViewV' : 'GameViewH';
        const adapter = director.getScene()?.getComponentsInChildren(GameViewAdapter).find(a => a.node.name === adapterName);
        if (!adapter) return;
        const lp = adapter.freeBoardContentLpos;
        if (lp && (lp.x !== 0 || lp.y !== 0 || lp.z !== 0)) content.setPosition(lp);
        const sc = adapter.freeBoardContentScale;
        if (sc && (sc.x !== 0 || sc.y !== 0 || sc.z !== 0)) content.setScale(sc);
    }

    show(): Promise<void> {
        this._dismissed = false;
        this._fading = false;
        const opacity = this.node.getComponent(UIOpacity);
        if (opacity) { Tween.stopAllByTarget(opacity); opacity.opacity = 255; }
        this.node.active = true;

        // 播 begin (one-shot) → loop
        if (trySetAnimation(this.spine, 'begin', false, 'FreeBoardView.show')) {
            this.spine.setCompleteListener(() => {
                this.spine.setCompleteListener(null!);
                if (!this.node?.isValid || this._dismissed) return;
                trySetAnimation(this.spine, 'loop', true, 'FreeBoardView.show');
            });
        }

        this.scheduleOnce(this.autoDismiss, AUTO_DISMISS_SEC);

        return new Promise<void>((resolve) => {
            this._resolveClose = resolve;
        });
    }

    private onTouchStart(): void {
        this.dismiss();
    }

    private dismiss(): void {
        if (this._dismissed) return;
        this._dismissed = true;
        this.unschedule(this.autoDismiss);

        this.playEnd();
        // 開始播 end 流程就繼續 轉場與 end 同時進行
        this._resolveClose?.();
        this._resolveClose = null;
    }

    // 播 end 動畫 播完才淡出收掉
    private playEnd(): void {
        this.spine.setCompleteListener(null!);
        if (!trySetAnimation(this.spine, 'end', false, 'FreeBoardView.playEnd')) {
            this.close();
            return;
        }
        this.spine.setCompleteListener(() => this.close());
        this.scheduleOnce(this.finishClose, END_FALLBACK_SEC);
    }

    // 整個彈窗淡出到透明後才關閉
    private close(): void {
        this.unschedule(this.finishClose);
        this.spine.setCompleteListener(null!);
        if (this._fading) return;
        this._fading = true;
        const opacity = this.node.getComponent(UIOpacity) ?? this.node.addComponent(UIOpacity);
        Tween.stopAllByTarget(opacity);
        tween(opacity)
            .to(CLOSE_FADE_SEC, { opacity: 0 })
            .call(() => {
                this._fading = false;
                if (this.node?.isValid) this.node.active = false;
            })
            .start();
    }

    protected override onDestroy(): void {
        this.disposeOrientation?.();
        this.disposeOrientation = null;
        this.unscheduleAllCallbacks();
        this.node.off(Node.EventType.TOUCH_START, this.onTouchStart, this);
    }
}
