import type { SlotRoundResult } from '../models/SlotRound';

/**
 * 純資料流程規劃：只描述「該加入哪些 Task、依什麼順序」，不 import cc／View／具體 Task class，
 * 也不執行任何演出。`SpinResultHandler` 依這份規劃結果組裝實際 Task；Node 測試環境可以直接
 * 用真實 fixture 驗證這裡的決策，不需要假的 Cocos 引擎。
 *
 * 跟 1001 的 SpinFlowPlanner 結構相同，但不是同一份共用實作——1002 目前沒有 Jackpot 彈窗
 * 能力（沒有 JackpotView，PopupManager 沒有對應處理），所以規劃結果不會有 jackpot 這個 kind；
 * 免費遊戲進場也是直接呼叫 game.showFreeBoard()，不是 1001 那個獨立的 WinFreeGamePopupTask。
 */
export type SpinFlowStep =
    | { readonly kind: 'collectWin'; readonly mainMult: number; readonly spinWin: number }
    | { readonly kind: 'scatterWin' }
    | { readonly kind: 'finishSpin'; readonly spinWin: number }
    | { readonly kind: 'winAnimation'; readonly spinWin: number }
    | { readonly kind: 'endSpin' }
    | { readonly kind: 'showFreeBoard' }
    | { readonly kind: 'enterFreeGame'; readonly freeRoundCount: number }
    | { readonly kind: 'playFreeRound'; readonly freeRoundIndex: number }
    /** 玩家端 API：免費遊戲每一轉在播放時才向後端要，一直播到局結束，結束後再排收尾 */
    | { readonly kind: 'playFreeGame' }
    | { readonly kind: 'fgDelay' }
    | { readonly kind: 'exitFreeGame' };

/**
 * 依 SlotRoundResult 規劃一局 Spin 完整流程。
 *
 * willEnterFreeGame 需要外部傳入：是否進 FG 還要看「當下盤面實際 scatter 數」跟「玩家是否
 * pending buy feature」這兩個依賴即時畫面／外部狀態的條件，規劃器本身只認後端權威資料
 * （SlotRoundResult.freeSpinTriggered／freeRounds），不會自己猜盤面。
 */
export function planSpinFlow(roundResult: SlotRoundResult, willEnterFreeGame: boolean): SpinFlowStep[] {
    const steps: SpinFlowStep[] = [];
    const mainMult = roundResult.multiplier || 0;
    const spinWin = Number(roundResult.totalWin) || 0;

    // 沒有贏分跳過收集演出：mainMult 只代表盤面上有倍率球，不代表這局真的有中獎
    if (mainMult > 0 && spinWin > 0) {
        steps.push({ kind: 'collectWin', mainMult, spinWin });
    }

    if (willEnterFreeGame) {
        // 同一局有贏分 先報獎再進免費遊戲
        steps.push({ kind: 'winAnimation', spinWin });
        steps.push({ kind: 'scatterWin' });
        steps.push({ kind: 'showFreeBoard' });
        appendFreeGameSteps(steps, roundResult);
        return steps;
    }

    steps.push({ kind: 'finishSpin', spinWin });
    steps.push({ kind: 'winAnimation', spinWin });
    steps.push({ kind: 'endSpin' });
    return steps;
}

function appendFreeGameSteps(steps: SpinFlowStep[], roundResult: SlotRoundResult): void {
    const spinWin = Number(roundResult.totalWin) || 0;
    const lazy = roundResult.freeSpinsTotal !== undefined;
    const freeRoundCount = roundResult.freeSpinsTotal ?? roundResult.freeRounds.length;
    if (freeRoundCount === 0) {
        steps.push({ kind: 'finishSpin', spinWin });
        steps.push({ kind: 'endSpin' });
        return;
    }

    steps.push({ kind: 'enterFreeGame', freeRoundCount });
    if (lazy) {
        steps.push({ kind: 'playFreeGame' });
        return;
    }

    for (let i = 0; i < freeRoundCount; i++) {
        steps.push({ kind: 'playFreeRound', freeRoundIndex: i });
        if (i < freeRoundCount - 1) steps.push({ kind: 'fgDelay' });
    }
    steps.push({ kind: 'exitFreeGame' });
}
